// DEMO: stands in for 'Fetch WhatsApp' — emits one synthetic post so the pipeline
// can run end-to-end with no real WhatsApp Business number/token.
return [{ json: {
  id: 'demo-post-' + Date.now(),
  caption: 'NMD Associates — demo post, not real content.',
  publicUrl: 'https://picsum.photos/seed/nmd-demo/800/800'
} }];

// Same dedup logic as production: create a per-platform entry for any post not seen before.
const store = $getWorkflowStaticData('global');
store.published = store.published || {};
const out = [];
for (const item of $input.all()) {
  const id = item.json.id;
  if (!id) continue;
  if (!store.published[id]) {
    store.published[id] = { instagram: false, facebook: false, linkedin: false };
  }
  out.push({ json: { ...item.json, dedupId: id } });
}
return out;

// DEMO: skip if already published to Instagram this post (same logic as production).
const store = $getWorkflowStaticData('global');
return $input.all().filter(item => !(store.published[item.json.dedupId] || {}).instagram);

// Response from the publish call replaced item.json, so pull dedupId/caption back from the pre-call state.
const upstream = $('IF Instagram Pending').all();
return $input.all().map((item, i) => ({ json: { ...upstream[i].json, igPublished: true } }));

// DEMO: skip if already published to Facebook this post (same logic as production).
const store = $getWorkflowStaticData('global');
return $input.all().filter(item => !(store.published[item.json.dedupId] || {}).facebook);

// Response from the publish call replaced item.json, so pull dedupId/caption back from the pre-call state.
const upstream = $('IF Facebook Pending').all();
return $input.all().map((item, i) => ({ json: { ...upstream[i].json, fbPublished: true } }));

// DEMO: skip if already published to LinkedIn this post (same logic as production).
const store = $getWorkflowStaticData('global');
return $input.all().filter(item => !(store.published[item.json.dedupId] || {}).linkedin);

// Response from the publish call replaced item.json, so pull dedupId/caption back from the pre-call state.
const upstream = $('IF LinkedIn Pending').all();
return $input.all().map((item, i) => ({ json: { ...upstream[i].json, liPublished: true } }));

// Same save logic as production: flip only the flags for branches that actually ran+succeeded.
const store = $getWorkflowStaticData('global');
for (const item of $input.all()) {
  const id = item.json.dedupId;
  if (!id || !store.published[id]) continue;
  if (item.json.igPublished) store.published[id].instagram = true;
  if (item.json.fbPublished) store.published[id].facebook = true;
  if (item.json.liPublished) store.published[id].linkedin = true;
}
return [{ json: { finalDedupMap: store.published } }];
